def main():
    draft = A/'ILLUSION_NECROMANCY_RANK4_OPERATING_PROPOSALS.json'
    out = R/'data/director/spell_proposals/illusion_necromancy_rank4.json'
    doc = R/'docs/spells/proposals/ILLUSION_NECROMANCY_RANK4.md'
    receipt = A/'ILLUSION_NECROMANCY_RANK4_OPERATING_PROPOSAL_CHECK.json'
    assert not any(p.exists() for p in [draft, out, doc, receipt]), 'Preserve old outputs before revision.'
    prep_path = A/'ILLUSION_NECROMANCY_RANK4_SOURCE_PREPARATION.json'
    cat_path = R/'data/public/spell_playtests/catalog.json'
    idx_path = cat_path.with_name('authored_review_index.json')
    prep, cat, idx = read(prep_path), read(cat_path), read(idx_path)
    selected = {s['spellId']: s for s in prep['selectedSpells']}
    catalog = {s['id']: s for s in cat['spells']}
    entries = {s['id']: s for s in idx['entries']}
    checks = []
    def check(name, condition):
        checks.append({'name': name, 'pass': bool(condition)})
        assert condition, name
    check('All thirteen distinct original IN4 identities', len(P) == len({p['spellId'] for p in P}) == 13 and {p['spellId'] for p in P} == set(selected))
    check('No post-push receipt authored', all(s['scope'] == 'pre-push mechanical source question' for s in selected.values()))
    check('Ordinary catalog totals unchanged', len(catalog) == 848 and idx['authoredCounts'] == {'reviewed': 412, 'pending': 436})
    inputs = {prep_path, cat_path, idx_path, Path(__file__).resolve()}
    records = []
    for p in P:
        s = selected[p['spellId']]; original = catalog[p['spellId']]
        digest = sha256(json.dumps(original, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
        check(p['spellId']+' complete source/access unchanged', original == s['fullSourceAndCurrentAccessRecord'] and digest == s['recordSha256'])
        check(p['spellId']+' remains pending', entries[p['spellId']]['authoredStatus'] == 'pending-authored-procedure' and original['operational'] is None)
        check(p['spellId']+' complete examples', len(p['workedCases']) == 2 and all(len(e) > 150 for e in p['workedCases']))
        check(p['spellId']+' rank 4/base 7 preserved', all(v['rank']==4 and v['baseRpCost']==7 for v in original['classAccess'].values()))
        records.append({**p, 'questionId': s['questionId'], 'originalQuestion': s['individualQuestion'], 'fullSourceAndCurrentAccessRecord': original,
                        'sourceRecordSha256': digest, 'status':'unadopted-unsent-operating-proposal', 'examplesAreRuntimeTests':False})
    records.sort(key=lambda x:x['questionId'])
    counterparts = []
    for original in prep['completeCounterparts']:
        sid=original['id']; e=entries[sid]; f=cat_path.parent/e['procedureFile']; d=read(f); inputs.add(f)
        for k in e['wholeCardPointer'].strip('/').split('/'):
            d=d[int(k)] if isinstance(d,list) else d[k]
        check(sid+' whole current counterpart retrieved', d.get('id',d.get('spellId'))==sid)
        check(sid+' actual authored procedure present', isinstance(d.get('operational',d.get('operationalCandidate')),dict))
        counterparts.append({'id':sid,'preparedCompleteRecord':original,'currentSourceCatalogRecord':catalog[sid],
                             'currentAuthoredIndexEntry':e,'completeCurrentAuthoredRecord':d})
    check('All twenty-seven counterparts retrieved including seven later-reviewed low-rank entries', len(counterparts)==27)
    guides={}
    for x in prep['currentGoverningExcerpts']:
        p=G/x['file']; inputs.add(p)
        guides.setdefault(x['file'], {'currentFile':info(p),'fullCurrentText':p.read_text(encoding='utf-8'),'preparedExcerpts':[]})['preparedExcerpts'].append(x)
    for filename in ['CLASS_PLAYTEST_RULES.md','CUSTOM_CONDITION_BINDINGS.md','MAXIMUM_HP_PLAYTEST.md','COMBAT_ACTION_PLAYTEST.md']:
        p=R/'docs/mechanics'/filename; inputs.add(p)
        guides.setdefault(p.relative_to(G).as_posix(),{'currentFile':info(p),'fullCurrentText':p.read_text(encoding='utf-8'),'preparedExcerpts':[]})
    comparisons=[]
    for name in ['bard','cleric','crimson-agent','druid','mirrorsage','monk','oracle','ranger','shaman','thief','wizard']:
        p=R/'data/public/Decennium_Descent_Bard_Playtest_v0_1.json' if name=='bard' else R/f'data/public/class_playtests/{name}.json'
        d=read(p); inputs.add(p)
        comparisons.append({'path':p.relative_to(G).as_posix(),**info(p),'completeCurrentEnvelope':d})
    low_path=cat_path.parent/'candidate_low_rank_136.json'; lower=read(low_path); inputs.add(low_path)
    source_info={p.relative_to(G).as_posix():info(p) for p in sorted(inputs)}
    pending=read(A/'EX58_EXACT_CANDIDATE_PACKAGE.json')
    preserved=0
    for rel, expected in pending['manifest'].items():
        p=G/rel
        if p.is_file(): check('Submitted exact candidate unchanged: '+rel,info(p)==expected); preserved+=1
    arithmetic=[('Terrain maximum horizontal span',75*2,150),('Minute deadline',60,60),('Hour deadline',60*60,3600),
                ('Steed example pounds',170+25+10,205),('Steed example Load',205/10,20.5),('Golem critical dice',2*2,4),
                ('Golem half Speed',30/2,15),('Leech opportunities',[6*n for n in range(1,5)],[6,12,18,24]),
                ('Leech capped actual damage',3+min(9-3,4),7),('Leech base heal',(3+4)//2,3),
                ('Dread attack',12+5-1,16),('Soulburn committed RP',12-7,5),('Soulburn resolved RP',12-7+3,8),
                ('Soulburn committed HP',31-20,11),('Soulburn minimum normal HP',20+1,21),
                ('Blight plant dice',8+2,10),('Blight half then resistance',(47//2)//2,11),('Moil resistance',19//2,9),
                ('Cage exterior',10+2*1,12),('Cage Athletics success',11+4>=15,True)]
    for name,actual,expected in arithmetic:check(name,actual==expected)
    now=datetime.now(timezone.utc).isoformat()
    save(draft,{'status':SHARED['status'],'createdAtUtc':now,'sharedProposal':SHARED,'proposals':P,'explicitJointIssues':ISSUES})
    save(out,{'status':SHARED['status'],'createdAtUtc':now,'sharedProposal':SHARED,'records':records,'explicitJointIssues':ISSUES,
              'completeCurrentCounterparts':counterparts,'completeClassComparisons':comparisons,'currentGoverningDocuments':guides,
              'originalBookBindings':prep['currentBookBindings'],'completeOriginalPreparation':prep,'currentLowRankSharedRules':lower['sharedRules'],
              'sourceFiles':source_info,'runtimeImplemented':False,'cosmologyReviewed':False,'sourceInformationDeleted':0,'newPromotions':0})
    lines=['# Rank-four Illusion and Necromancy: operating proposals','','**UNADOPTED AND UNSENT.** Thirteen complete procedures and twenty-six authored examples. Original source, class access and historical versions remain intact. These await GPT discussion and exact review; examples are not runtime tests.','',
           '[Complete structured evidence](../../../data/director/spell_proposals/illusion_necromancy_rank4.json) · [Original questions](../../../../../docs/audit/2026-10-08/full-game/ILLUSION_NECROMANCY_RANK4_SOURCE_AUDIT.md) · [Preservation checks](../../../../../docs/audit/2026-10-08/full-game/ILLUSION_NECROMANCY_RANK4_OPERATING_PROPOSAL_CHECK.json)','','## Shared proposed rules','']
    for key, value in SHARED.items():lines+=['### '+key,'',value,'']
    lines+=['## Decisions for joint review','']
    for issue in ISSUES:lines+=['- '+issue,'']
    for rec in records:
        f=rec['fullSourceAndCurrentAccessRecord']; lines+=['## '+rec['questionId']+' — '+f['name'],'','**Original placements, unchanged**','']
        for place in f['source']['original']['placements']:lines+=['- '+place['school']+' rank '+str(place['level'])+': '+place['summary'],'']
        lines+=['**Proposed procedure**','',rec['procedure'],'','**Explicit NEW choices:** '+rec['newChoices'],'','**Authored examples**','']
        for example in rec['workedCases']:lines+=['- '+example,'']
        lines+=['<details><summary>Original question and complete source/access record</summary>','',rec['originalQuestion'],'','```json',json.dumps(f,ensure_ascii=False,indent=2),'```','','</details>','']
    doc.parent.mkdir(parents=True,exist_ok=True); doc.write_text('\n'.join(lines),encoding='utf-8',newline='\n')
    rendered=doc.read_text(encoding='utf-8')
    for rec in records:check(rec['spellId']+' complete procedure and source rendered',rec['procedure'] in rendered and json.dumps(rec['fullSourceAndCurrentAccessRecord'],ensure_ascii=False,indent=2) in rendered)
    for link in re.findall(r'\[[^\]]*\]\(([^)]+)\)',rendered):check('Document link '+link,(doc.parent/link).resolve().is_file() or (doc.parent/link).resolve()==receipt)
    check('Saved records match authored full records',read(out)['records']==records)
    for rel,expected in source_info.items():check('Authoring input unchanged: '+rel,info(G/rel)==expected)
    result={'status':SHARED['status'],'createdAtUtc':now,'originalSpellIdentities':13,'completeMechanicalProposals':13,'authoredExamples':26,
            'completeCurrentCounterparts':len(counterparts),'completeCurrentComparisonClasses':len(comparisons),'newJointIssues':len(ISSUES),
            'checks':len(checks),'failures':0,'plainArithmeticChecks':len(arithmetic),'fullSpellRuntimeCases':0,'submittedLocalFilesUnchanged':preserved,
            'ordinarySpellsReviewedUnchanged':412,'ordinarySpellsPendingUnchanged':436,'artifacts':{p.relative_to(G).as_posix():info(p) for p in [draft,out,doc]},
            'scope':'Source/submitted-file preservation, exact whole-card current counterpart retrieval, proposal rendering and twenty plain reference calculations. No independent semantic approval, runtime simulation or human balance result.',
            'sourceInformationDeleted':0,'cosmologyReviewed':False,'pushed':False,'details':checks}
    save(receipt,result); print(json.dumps({k:v for k,v in result.items() if k!='details'},ensure_ascii=False,indent=2))


if __name__=='__main__':
    main()
